export function ShadowToken({
  name = "{{name}}",
  blur = {{blur}},
  yOffset = {{yOffset}},
  target = "{{target}}",
}) {
  const shadow = `0 ${yOffset}px ${blur}px rgba(36,20,48,.22)`;
  const base = { display: "flex", background: "#ffffff", alignItems: "center", justifyContent: "center", boxShadow: shadow };
  let shape;
  if (target === "card") shape = <div style={{ ...base, width: 100, height: 60, borderRadius: 10 }}>Card</div>;
  else if (target === "button") shape = <div style={{ ...base, padding: "12px 22px", borderRadius: 8, fontWeight: 600 }}>Button</div>;
  else shape = <div style={{ ...base, width: 130, height: 60, borderRadius: 14 }}>Modal</div>;
  return (
    <div style={{ font: "14px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 20, borderRadius: 12, width: 280, boxSizing: "border-box" }}>
      <code style={{ display: "block", marginBottom: 20, padding: "8px 10px", background: "#24143012", borderRadius: 6, font: "11px/1.4 ui-monospace, monospace", wordBreak: "break-all" }}>--{name}: {shadow};</code>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "center", height: 80 }}>{shape}</div>
    </div>
  );
}
